"""Atlas content for patch 6.0, MSQ #732 His Park Materials to #760 At World's End. Arc tag w. Data only
(docs/atlas/era-modules.md is the contract).

Researched 2026-11-19 from the saved Console Games Wiki wikitext (lanes W07–W12); every locator is an exact substring
of a quest's Journal, Steps or main dialogue (stage directions inside cutscenes included). Spoiler rules this module
follows:
  - first names and titles only: no "Leveilleur", "Galvus", "Junius", "viator"; Fourchenault is "Master Fourchenault";
  - Sharlayan, Garlemald and Radz-at-Han stay text-only, because accepted text already names them long before this era
    (an entity first visible here would fail the leak check on those earlier records);
  - the flower's ancient name, the facility Elidibus points to and the man who ran it stay out of text (later eras);
  - minor Loporrits, the Palaka's Stand couple and their child are described, not named (incidental NPCs);
  - the Forum is "The Forum of Sharlayan", since accepted text already says "The Forum's envoy" at #697.
"""

def P(frm, until, scope, name, summary, claims, aliases=()):
    return dict(frm=frm, until=until, scope=scope, name=name, aliases=list(aliases), summary=summary, claims=claims)

X = {n: f"cp-msq-{n}" for n in range(732, 761)}
EX = ["The Crystal Exarch"]  # G'raha Tia's alias since the 5.0 reveal
VA = ["Varshahn"]  # Vrtra's alias since part 1's reveal at #709b (rel-varshahn-revealed-as-vrtra)

